import 'server-only';
import type { ResortRecord } from '@vacationpro/engine';
import CATALOG from '@/data/resorts/catalog.generated.json';

export * from './meta';

/**
 * Server-only access to the resort catalog (generated by
 * scripts/build-resort-catalog.mjs). About 1MB, so it must never be imported
 * from a client component: the matcher runs on the server and the browser
 * receives only the results. Browser code uses ./meta instead.
 */
export const RESORT_CATALOG: ResortRecord[] = CATALOG as unknown as ResortRecord[];

export const ACTIVE_RESORTS: ResortRecord[] = RESORT_CATALOG.filter((r) => r.status === 'active');

const BY_ID = new Map(RESORT_CATALOG.map((r) => [r.id, r]));

/** Any record, including hidden ones (for honest "not offered" messaging). */
export function getResortRecord(id: string): ResortRecord | null {
  return BY_ID.get(id) ?? null;
}

export function getActiveResort(id: string): ResortRecord | null {
  const r = BY_ID.get(id);
  return r && r.status === 'active' ? r : null;
}

export function resortsForDestination(slug: string): ResortRecord[] {
  return ACTIVE_RESORTS.filter((r) => r.destination === slug);
}

export function resortIdSet(): Set<string> {
  return new Set(BY_ID.keys());
}
